#include <stdio.h>


int main(void)
{
    int hash = 1, outgoing = 0, incoming = 0;
    hash = (hash - outgoing * 26 + 101) % 101;
    hash = (hash * 26 + incoming) % 101;
    printf("%d\n", hash);
    return 0;
}
